bool IsSmallPrime(
  int64_t number
) {
  for (int64_t prime : std::vector<int64_t>{2, 3, 5, 7}) {
    if (prime == number) {
      return true;
    }
  }
  return false;
}

std::vector<int64_t> CountAndLengthsOf(
  const std::vector<std::wstring>& texts
) {
  auto result = (
    std::vector<int64_t>{static_cast<int64_t>(texts.size())}
  );
  for (const std::wstring& text : texts) {
    result.push_back(static_cast<int64_t>(common::LenStr(text)));
  }
  return result;
}

std::vector<int64_t> PositivesOf(
  const std::vector<int64_t>& numbers
) {
  std::vector<int64_t> result = std::vector<int64_t>();
  for (int64_t number : numbers) {
    if (number > 0) {
      result.push_back(number);
    }
  }
  return result;
}

bool IntsAreUnique(
  const std::vector<int64_t>& numbers
) {
  std::vector<int64_t> seen = std::vector<int64_t>();
  for (int64_t number : numbers) {
    if (
      common::Contains(
        seen,
        number
      )
    ) {
      return false;
    }
    seen.push_back(number);
  }
  return true;
}

bool ContainsByLoop(
  int64_t number,
  const std::vector<int64_t>& numbers
) {
  for (int64_t other : numbers) {
    if (other == number) {
      return true;
    }
  }
  return false;
}

bool FloatsAreUnique(
  const std::vector<double>& numbers
) {
  for (size_t i = 0; i < numbers.size(); ++i) {
    for (size_t j = i + (1); j < numbers.size(); ++j) {
      if (numbers.at(i) == numbers.at(j)) {
        return false;
      }
    }
  }
  return true;
}

